def insert_after(text, anchor, block, label):
    """Inserisce `block` come nuova voce subito dopo la voce che termina in `anchor`."""
    i = text.find(anchor)
    if i < 0:
        raise SystemExit("%s: ancora non trovata" % label)
    # `anchor` termina con "      }\n    ]" : si inserisce una virgola e la nuova voce
    end = i + len(anchor)
    head, tail = text[:end], text[end:]
    if not head.endswith("      }\n    ]"):
        raise SystemExit("%s: forma inattesa" % label)
    head = head[: -len("\n    ]")] + ",\n" + block.rstrip("\n") + "\n    ]"
    return head + tail


